#!/usr/bin/env bash
set -euo pipefail

# Generated by RoleCraft — https://rolecraft.omhinge.cloud
# Creates an IAM role with its trust policy and permissions.

ROLE_NAME='github-deploy'

# Trust policy: who can assume the role
cat > trust.json <<'ROLECRAFT_EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Federated": "arn:aws:iam::123456789012:oidc-provider/token.actions.githubusercontent.com"
      },
      "Action": "sts:AssumeRoleWithWebIdentity",
      "Condition": {
        "StringEquals": {
          "token.actions.githubusercontent.com:aud": "sts.amazonaws.com",
          "token.actions.githubusercontent.com:sub": "repo:omhinge/site:ref:refs/heads/main"
        }
      }
    }
  ]
}
ROLECRAFT_EOF

# Permissions policy
cat > policy.json <<'ROLECRAFT_EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "S3ReadWriteList",
      "Effect": "Allow",
      "Action": "s3:ListBucket",
      "Resource": "arn:aws:s3:::site-assets"
    },
    {
      "Sid": "S3ReadWriteObjects",
      "Effect": "Allow",
      "Action": [
        "s3:AbortMultipartUpload",
        "s3:GetObject",
        "s3:GetObjectVersion",
        "s3:ListMultipartUploadParts",
        "s3:PutObject"
      ],
      "Resource": "arn:aws:s3:::site-assets/*"
    },
    {
      "Sid": "CloudfrontCustomScoped",
      "Effect": "Allow",
      "Action": "cloudfront:CreateInvalidation",
      "Resource": "arn:aws:cloudfront::123456789012:distribution/E2EXAMPLE"
    }
  ]
}
ROLECRAFT_EOF

# GitHub Actions needs an OIDC identity provider in this account (created once).
if ! aws iam list-open-id-connect-providers --query "OpenIDConnectProviderList[?ends_with(Arn, '/token.actions.githubusercontent.com')].Arn" --output text | grep -q .; then aws iam create-open-id-connect-provider --url https://token.actions.githubusercontent.com --client-id-list sts.amazonaws.com; fi

aws iam create-role --role-name "$ROLE_NAME" --assume-role-policy-document file://trust.json --description 'Created with RoleCraft'
POLICY_ARN=$(aws iam create-policy --policy-name "${ROLE_NAME}-policy" --policy-document file://policy.json --query Policy.Arn --output text)
aws iam attach-role-policy --role-name "$ROLE_NAME" --policy-arn "$POLICY_ARN"

echo "Created role $ROLE_NAME."
echo "Created and attached policy ${ROLE_NAME}-policy."
